import {esc} from './weather-tools.js';
export function communityRules(){return `<section><h1>Le regole del cielo</h1><ol><li>Racconta solo il meteo che osservi, con foto pertinenti e senza dati personali.</li><li>Niente offese, spam, contenuti pericolosi o segnalazioni inventate.</li><li>I contenuti segnalati vengono oscurati; il gestore può rimuoverli e bloccare nuove pubblicazioni.</li></ol><p>Le osservazioni scadono dopo 2 ore. Il gestore può esaminarle nel pannello riservato per 24 ore dalla pubblicazione. Non è un canale di emergenza.</p><a href="#community">Torna alla community</a></section>`}
export function createModeration({api,toast}){
 let run=0,until=null,next=null;
 const $=s=>document.querySelector(s);
 function page(){return `<section><h1>Moderazione</h1><p>Area riservata al gestore. Esamina i contenuti delle ultime 24 ore, compresi quelli oscurati o scaduti.</p><div id="moderation-content" aria-live="polite"><p>Verifico l’accesso…</p></div></section>`}
 function login(message=''){const host=$('#moderation-content');if(!host)return;host.innerHTML=`<form id="moderation-login"><label class="field">Password del gestore<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><button class="button">Accedi</button><p role="status">${esc(message)}</p></form>`;$('#moderation-login').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),password=form.elements.password.value;form.elements.password.value='';button.disabled=true;try{await api('moderation/login',{password});if(form.isConnected)await load()}catch(error){if(form.isConnected)login(error.message)}}}
 async function load(more=false){const token=++run;try{const result=await api('moderation/reports'+(more?'?'+new URLSearchParams({offset:next,until}):''));if(token!==run||!$('#moderation-content'))return;until=result.until;next=result.next;const host=$('#moderation-content');if(!more)host.innerHTML='<div class="actions"><button data-mod-refresh>Aggiorna elenco</button><button data-mod-logout>Esci dal pannello</button></div><p>Le segnalazioni per abuso sono oscurate subito. La revisione e la rimozione entro 24 ore richiedono l’intervento del gestore.</p><div id="moderation-list"></div><p id="moderation-empty"></p><button data-mod-more>Altri contenuti</button>';
 $('#moderation-list').insertAdjacentHTML('beforeend',result.reports.map(r=>`<article class="card"><h2>${esc(r.phenomenon||r.kind)}</h2><p>${esc(r.name)} · ${esc(r.city)} · ${new Date(r.created).toLocaleString('it-IT')} · ${r.source==='sky'?'Segnalazione':r.source==='schools'?'Scuole':'Post'}</p><p>${r.deleted?'Rimosso':r.hidden?'Oscurato':r.expires&&r.expires<Date.now()?'Scaduto':'Visibile'}</p>${r.text?`<p>${esc(r.text)}</p>`:''}${r.reasons?`<p><strong>Motivi della segnalazione:</strong> ${esc(r.reasons)}</p>`:''}${r.photo&&!r.deleted?`<img src="/api/moderation/media/${r.source}/${encodeURIComponent(r.id)}" alt="Foto da esaminare" loading="lazy" style="max-width:100%;height:auto">`:''}<div class="actions">${!r.deleted?`<button data-mod-remove="${r.id}" data-source="${r.source}">Rimuovi contenuto</button>`:''}<button data-mod-ban="${r.id}" data-source="${r.source}">Blocca autore e browser riconosciuti</button></div></article>`).join(''));
 $('#moderation-empty').textContent=$('#moderation-list').children.length?'':'Nessun contenuto nelle ultime 24 ore.';$('[data-mod-more]').hidden=next===null;
 $('[data-mod-more]').onclick=()=>load(true);$('[data-mod-refresh]').onclick=()=>load();$('[data-mod-logout]').onclick=async()=>{try{await api('moderation/logout',{});run++;login()}catch(error){toast(error.message)}};
 host.querySelectorAll('[data-mod-remove],[data-mod-ban]').forEach(b=>b.onclick=async()=>{b.disabled=true;const action=b.hasAttribute('data-mod-ban')?'ban':'remove';try{const result=await api('moderation/'+action,{id:b.dataset.modBan||b.dataset.modRemove,source:b.dataset.source});toast(result.message||'Contenuto rimosso.');await load()}catch(error){toast(error.message);b.disabled=false;if(error.status===401)login(error.message)}});
 }catch(error){if(token!==run||!$('#moderation-content'))return;if(error.status===401)login();else{$('#moderation-content').innerHTML=`<p role="alert">${esc(error.message)}</p><button id="mod-retry">Riprova</button>`;$('#mod-retry').onclick=()=>load()}}}
 function bind(){if($('#moderation-content')){until=next=null;load()}}
 return {page,bind};
}
